import type { Metadata } from "next";

import { StudentsFilter } from "@/components/admin/students-filter";
import { StudentsPagination } from "@/components/admin/students-pagination";
import { StudentsTable } from "@/components/admin/students-table";

export const metadata: Metadata = {
  title: "Students — Admin — BJS Prep",
  description: "Manage all registered students.",
};

export default function StudentsPage() {
  return (
    <div className="mx-auto max-w-6xl">
      <header className="flex flex-col gap-2 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="font-heading text-3xl font-bold text-primary lg:text-4xl">
            Students
          </h1>
          <p className="mt-2 text-base text-muted">143 registered accounts.</p>
        </div>
        <button
          type="button"
          disabled
          className="h-10 w-fit rounded-md border border-border px-4 text-sm text-foreground opacity-60"
        >
          Export CSV
        </button>
      </header>

      <StudentsFilter />
      <StudentsTable />
      <StudentsPagination />
    </div>
  );
}
